    _ = econfig;

    // Bootstrap resampling variance becsléshez
    var variance = try Tensor.zeros(self.allocator, quantum_fisher.shape.dims);
    defer variance.deinit();

    for (variance.data, quantum_fisher.data, classical_fisher.data) |*v, qf, cf| {
