### Geometriai integrátorok szimplektikus optimalizáláshoz

A Hamilton-mechanika alapú optimalizálás megőrzi a rendszer energiáját és javítja a stabilitást:

```zig
pub const SymplecticConfig = struct {
    mass: f32 = 1.0,
    friction: f32 = 0.1,
    num_leapfrog_steps: usize = 10,
    step_size: f32 = 0.01,
};

pub fn symplecticUpdate(self: *SFD, gradients: *const Tensor, params: *Tensor, velocities: *Tensor, sconfig: SymplecticConfig) !void {
    // Leapfrog integrátor (szimplektikus)
    // v_{t+1/2} = v_t - (dt/2) * ∇U(q_t) / m
    // q_{t+1} = q_t + dt * v_{t+1/2}
    // v_{t+1} = v_{t+1/2} - (dt/2) * ∇U(q_{t+1}) / m

    const dt = sconfig.step_size;
    const half_dt = dt * 0.5;
    const inv_mass = 1.0 / sconfig.mass;

    // Half velocity update
    for (velocities.data, gradients.data) |*v, g| {
        v.* -= half_dt * g * inv_mass;
    }

    // Position update
    for (params.data, velocities.data) |*p, v| {
        p.* += dt * v;
    }

    // Compute new gradient
    var new_grad = try self.gradient(null, params, null);
    defer new_grad.deinit();

    // Half velocity update again
    for (velocities.data, new_grad.data) |*v, g| {
        v.* -= half_dt * g * inv_mass;
        // Friction
        v.* *= (1.0 - sconfig.friction);
    }

    // Fisher preconditioning
    for (velocities.data, self.fisher_diag.data) |*v, f| {
        v.* /= (std.math.sqrt(f) + self.eps);
    }
}
