pub fn multiObjectiveUpdate(self: *SFD, objective_gradients: []const Tensor, params: *Tensor, pareto_archive: []ParetoSolution, moconfig: MultiObjectiveConfig) !void {
    // Scalarize objectives
    var combined_grad = try Tensor.zeros(self.allocator, params.shape.dims);
    defer combined_grad.deinit();

    const weight_per_obj = 1.0 / @as(f32, @floatFromInt(objective_gradients.len));

    for (objective_gradients) |obj_grad| {
        for (combined_grad.data, obj_grad.data) |*cg, og| {
            cg.* += weight_per_obj * og;
        }
    }

    // Pareto-improvement irány számítás
    const pareto_direction = try self.computeParetoDirection(&combined_grad, pareto_archive);
    defer pareto_direction.deinit();

    // Update Pareto irányba
    try self.update(&pareto_direction, params, 0.01);

    // Pareto archive frissítés
    try self.updateParetoArchive(params, pareto_archive, moconfig);
}

fn computeParetoDirection(self: *SFD, grad: *const Tensor, pareto_archive: []ParetoSolution) !Tensor {
    _ = pareto_archive;
