const std = @import("std");
const Allocator = std.mem.Allocator;
const Tensor = @import("../core/tensor.zig").Tensor;

pub const LossFn = *const fn (params: *const Tensor, context: ?*anyopaque) anyerror!f32;

pub const SFDConfig = struct {
    beta1: f32 = 0.9,
    beta2: f32 = 0.999,
    eps: f32 = 1e-8,
    clip_threshold: f32 = 1.0,
    fisher_max: f32 = 1e6,
    warmup_steps: usize = 10,
    finite_diff_eps: f32 = 1e-5,
    second_order_eps: f32 = 1e-4,
};

pub const UltraOptimizerConfig = struct {
    param_size: usize,
    num_layers: usize = 8,
    sfd_config: SFDConfig = .{},
    use_soap_extension: bool = true,
    enable_fopng: bool = true,
    enable_qiaso: bool = false,
    enable_verification: bool = false,
    enable_privacy: bool = false,
    nested_update_interval: usize = 100,
    kronecker_power_iterations: usize = 5,
    shampoo_precond_update_freq: usize = 10,
    variance_buffer_size: usize = 50,
    temporal_decay: f32 = 0.01,
    surprise_threshold: f32 = 2.0,
    spectral_adaptation_rate: f32 = 0.1,
    privacy_epsilon: f32 = 1.0,
    gradient_clip_norm: f32 = 1.0,
    trust_region_radius: f32 = 0.1,
    temperature: f32 = 1.0,
    nesterov_momentum: f32 = 0.9,
    meta_lr: f32 = 0.001,
    num_quantum_candidates: usize = 8,
    collapse_threshold: f32 = 0.8,
};

pub const SFD = struct {
    fisher_diag: Tensor,
    momentum_buffer: Tensor,
    velocity_buffer: Tensor,
    beta1: f32,
    beta2: f32,
    eps: f32,
    clip_threshold: f32,
    fisher_max: f32,
    warmup_steps: usize,
    step_count: usize,
    allocator: Allocator,
    param_size: usize,
    initialized: bool,

    pub fn init(allocator: Allocator, param_size: usize) !SFD {
        return initWithConfig(allocator, param_size, .{});
    }

    pub fn initWithConfig(allocator: Allocator, param_size: usize, config: SFDConfig) !SFD {
        if (param_size == 0) return error.InvalidParamSize;
        if (config.beta1 <= 0.0 or config.beta1 >= 1.0) return error.InvalidBeta1;
        if (config.beta2 <= 0.0 or config.beta2 >= 1.0) return error.InvalidBeta2;
        if (config.eps <= 0.0) return error.InvalidEpsilon;
        if (config.clip_threshold <= 0.0) return error.InvalidClipThreshold;

        const shape = [_]usize{param_size};

        var diag = try Tensor.init(allocator, &shape);
        errdefer diag.deinit();
        try diag.fill(1.0);

        var momentum = try Tensor.init(allocator, &shape);
        errdefer momentum.deinit();
        try momentum.fill(0.0);

        var velocity = try Tensor.init(allocator, &shape);
        errdefer velocity.deinit();
        try velocity.fill(0.0);

        return SFD{
            .fisher_diag = diag,
            .momentum_buffer = momentum,
            .velocity_buffer = velocity,
            .beta1 = config.beta1,
            .beta2 = config.beta2,
            .eps = config.eps,
            .clip_threshold = config.clip_threshold,
            .fisher_max = config.fisher_max,
            .warmup_steps = config.warmup_steps,
            .step_count = 0,
            .allocator = allocator,
            .param_size = param_size,
            .initialized = true,
        };
    }

    pub fn deinit(self: *SFD) void {
        if (!self.initialized) return;
        self.fisher_diag.deinit();
        self.momentum_buffer.deinit();
        self.velocity_buffer.deinit();
        self.initialized = false;
    }

    pub fn update(self: *SFD, gradients: *const Tensor, params: *Tensor, lr: f32) !void {
        if (!self.initialized) return error.NotInitialized;
        if (!std.math.isFinite(lr) or lr < 0.0) return error.InvalidLearningRate;

        const grad_count = gradients.data.len;
        const param_count = params.data.len;

        if (grad_count != param_count) return error.ShapeMismatch;
        if (grad_count != self.param_size) return error.ShapeMismatch;

        self.step_count +|= 1;
        const step_f = @as(f32, @floatFromInt(self.step_count));

        const grad_data = gradients.data;
        const param_data = params.data;
        const momentum_data = self.momentum_buffer.data;
        const velocity_data = self.velocity_buffer.data;
        const fisher_data = self.fisher_diag.data;

        const warmup_steps_f = @as(f32, @floatFromInt(self.warmup_steps));
        const warmup_factor: f32 = if (self.step_count <= self.warmup_steps and self.warmup_steps > 0)
            step_f / warmup_steps_f
        else
            1.0;

        const beta1_power = std.math.pow(f32, self.beta1, step_f);
        const beta2_power = std.math.pow(f32, self.beta2, step_f);
        const m_correction = 1.0 - beta1_power;
        const v_correction = 1.0 - beta2_power;

        var i: usize = 0;
        while (i < self.param_size) : (i += 1) {
            const g = grad_data[i];

            if (!std.math.isFinite(g)) continue;

            momentum_data[i] = self.beta1 * momentum_data[i] + (1.0 - self.beta1) * g;
            velocity_data[i] = self.beta2 * velocity_data[i] + (1.0 - self.beta2) * g * g;

            var m_hat = momentum_data[i];
            var v_hat = velocity_data[i];

            if (m_correction > 1e-10) {
                m_hat = momentum_data[i] / m_correction;
            }
            if (v_correction > 1e-10) {
                v_hat = velocity_data[i] / v_correction;
            }

            const sqrt_v = std.math.sqrt(@max(0.0, v_hat));
            const adaptive_lr = lr * warmup_factor / (sqrt_v + self.eps);

            fisher_data[i] = self.beta2 * fisher_data[i] + (1.0 - self.beta2) * g * g;
            fisher_data[i] = @min(fisher_data[i], self.fisher_max);
            if (!std.math.isFinite(fisher_data[i])) {
                fisher_data[i] = 1.0;
            }

            const sqrt_fisher = std.math.sqrt(@max(0.0, fisher_data[i]));
            var update_val = m_hat * adaptive_lr / (sqrt_fisher + self.eps);

            update_val = std.math.clamp(update_val, -self.clip_threshold, self.clip_threshold);

            if (std.math.isFinite(update_val)) {
                param_data[i] -= update_val;
            }
        }
    }

    pub fn adaptiveLR(self: *const SFD, grad_norm: f32, param_norm: f32) f32 {
        if (!std.math.isFinite(grad_norm) or grad_norm < 0.0) return 1.0;
        if (!std.math.isFinite(param_norm) or param_norm < 0.0) return 1.0;

        const denom = param_norm + self.eps;
        const ratio = grad_norm / denom;
        const inner = ratio + self.eps;

        if (inner <= 0.0) return 1.0;

        const result = 1.0 / std.math.sqrt(inner);
        return if (std.math.isFinite(result)) result else 1.0;
    }

    pub fn spectralClip(self: *SFD, tensor: *Tensor, max_eig: f32) !void {
        if (!self.initialized) return error.NotInitialized;
        if (!std.math.isFinite(max_eig) or max_eig <= 0.0) return error.InvalidMaxEig;

        const current_max_ev = try tensor.spectralNorm(self.allocator, 100, 1e-6);
        if (!std.math.isFinite(current_max_ev) or current_max_ev <= 0.0) return;

        if (current_max_ev > max_eig) {
            const scale = std.math.sqrt(max_eig / current_max_ev);
            if (std.math.isFinite(scale) and scale > 0.0) {
                try tensor.mulScalar(scale);
            }
        }
    }

    pub fn accumulateFisher(self: *SFD, grads: []const Tensor) !void {
        if (!self.initialized) return error.NotInitialized;
        if (grads.len == 0) return;

        const fisher_data = self.fisher_diag.data;

        for (grads) |grad| {
            const g_data = grad.data;
            const count = @min(fisher_data.len, g_data.len);

            var j: usize = 0;
            while (j < count) : (j += 1) {
                const g = g_data[j];
                if (std.math.isFinite(g)) {
                    fisher_data[j] += g * g;
                    fisher_data[j] = @min(fisher_data[j], self.fisher_max);
                }
            }
        }
    }

    pub fn resetFisher(self: *SFD) void {
        if (!self.initialized) return;

        for (self.fisher_diag.data) |*val| {
            val.* = 1.0;
        }
    }

    pub fn clipGradNorm(self: *SFD, grads: []*Tensor, max_norm: f32) f32 {
        if (!std.math.isFinite(max_norm) or max_norm <= 0.0) return 0.0;

        var total_norm_sq: f64 = 0.0;

        for (grads) |grad| {
            const norm = grad.normL2();
            if (std.math.isFinite(norm)) {
                total_norm_sq += @as(f64, norm) * @as(f64, norm);
            }
        }

        const total_norm: f32 = @floatCast(std.math.sqrt(total_norm_sq));

        if (total_norm > max_norm) {
            const scale = max_norm / (total_norm + self.eps);
            if (std.math.isFinite(scale) and scale > 0.0) {
                for (grads) |grad| {
                    grad.mulScalar(scale) catch {};
                }
            }
        }

        return total_norm;
    }
};

pub const KroneckerFactor = struct {
    left: Tensor,
    right: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, left_size: usize, right_size: usize) !KroneckerFactor {
        const left_shape = [_]usize{ left_size, left_size };
        const right_shape = [_]usize{ right_size, right_size };

        var left = try Tensor.init(allocator, &left_shape);
        errdefer left.deinit();
        try left.fill(1.0);

        var right = try Tensor.init(allocator, &right_shape);
        errdefer right.deinit();
        try right.fill(1.0);

        return KroneckerFactor{
            .left = left,
            .right = right,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *KroneckerFactor) void {
        self.left.deinit();
        self.right.deinit();
    }
};

pub const AdaptiveSpectralRegularizer = struct {
    target_spectral_norm: f32,
    adaptation_rate: f32,
    history: std.ArrayList(f32),
    history_capacity: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, initial_target: f32, adaptation_rate: f32, capacity: usize) !AdaptiveSpectralRegularizer {
        return AdaptiveSpectralRegularizer{
            .target_spectral_norm = initial_target,
            .adaptation_rate = adaptation_rate,
            .history = std.ArrayList(f32).init(allocator),
            .history_capacity = capacity,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *AdaptiveSpectralRegularizer) void {
        self.history.deinit();
    }

    pub fn adaptiveClip(self: *AdaptiveSpectralRegularizer, tensor: *Tensor) !void {
        const current_norm = try tensor.spectralNorm(self.allocator, 100, 1e-6);

        if (self.history.items.len >= self.history_capacity) {
            var sum: f64 = 0.0;
            for (self.history.items) |val| sum += val;
            const mean = @as(f32, @floatCast(sum / @as(f64, @floatFromInt(self.history.items.len))));

            var variance: f64 = 0.0;
            for (self.history.items) |val| {
                const diff = val - mean;
                variance += @as(f64, diff) * @as(f64, diff);
            }
            const stddev = @as(f32, @floatCast(std.math.sqrt(variance / @as(f64, @floatFromInt(self.history.items.len)))));

            self.target_spectral_norm = mean + 0.5 * stddev;
        }

        if (current_norm > self.target_spectral_norm) {
            const ratio = current_norm / self.target_spectral_norm;
            const scale = 1.0 / (1.0 + self.adaptation_rate * (ratio - 1.0));
            try tensor.mulScalar(scale);
        }

        try self.history.append(current_norm);
        if (self.history.items.len > self.history_capacity) {
            _ = self.history.orderedRemove(0);
        }
    }
};

pub const VarianceReducedBuffer = struct {
    buffer: std.ArrayList(Tensor),
    capacity: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, capacity: usize) VarianceReducedBuffer {
        return VarianceReducedBuffer{
            .buffer = std.ArrayList(Tensor).init(allocator),
            .capacity = capacity,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *VarianceReducedBuffer) void {
        for (self.buffer.items) |*tensor| {
            tensor.deinit();
        }
        self.buffer.deinit();
    }

    pub fn push(self: *VarianceReducedBuffer, tensor: Tensor) !void {
        const cloned = try tensor.clone();
        try self.buffer.append(cloned);

        if (self.buffer.items.len > self.capacity) {
            var oldest = self.buffer.orderedRemove(0);
            oldest.deinit();
        }
    }

    pub fn computeMean(self: *const VarianceReducedBuffer) !Tensor {
        if (self.buffer.items.len == 0) return error.EmptyBuffer;

        const first = &self.buffer.items[0];
        var result = try Tensor.zeros(self.allocator, first.shape.dims);

        for (self.buffer.items) |*tensor| {
            for (result.data, 0..) |*val, i| {
                val.* += tensor.data[i];
            }
        }

        const divisor = @as(f32, @floatFromInt(self.buffer.items.len));
        for (result.data) |*val| {
            val.* /= divisor;
        }

        return result;
    }
};

pub const MetaOptimizer = struct {
    learning_rate: f32,
    beta1: f32,
    beta2: f32,
    epsilon: f32,
    weight_decay: f32,
    meta_lr: f32,
    validation_history: std.ArrayList(f32),
    allocator: Allocator,

    pub fn init(allocator: Allocator, initial_lr: f32, meta_lr: f32) !MetaOptimizer {
        return MetaOptimizer{
            .learning_rate = initial_lr,
            .beta1 = 0.9,
            .beta2 = 0.999,
            .epsilon = 1e-8,
            .weight_decay = 0.01,
            .meta_lr = meta_lr,
            .validation_history = std.ArrayList(f32).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *MetaOptimizer) void {
        self.validation_history.deinit();
    }

    pub fn metaUpdate(self: *MetaOptimizer, train_loss: f32, validation_loss: f32) !void {
        const prev_val_loss = if (self.validation_history.items.len > 0)
            self.validation_history.items[self.validation_history.items.len - 1]
        else
            validation_loss;

        const d_val_loss = validation_loss - prev_val_loss;

        const lr_grad = d_val_loss / (self.learning_rate + 1e-8);
        const beta1_grad = d_val_loss / (1.0 - self.beta1 + 1e-8);
        const beta2_grad = d_val_loss / (1.0 - self.beta2 + 1e-8);

        self.learning_rate -= self.meta_lr * lr_grad;
        self.beta1 -= self.meta_lr * beta1_grad * 0.1;
        self.beta2 -= self.meta_lr * beta2_grad * 0.1;

        self.learning_rate = std.math.clamp(self.learning_rate, 1e-6, 1.0);
        self.beta1 = std.math.clamp(self.beta1, 0.8, 0.999);
        self.beta2 = std.math.clamp(self.beta2, 0.9, 0.9999);

        try self.validation_history.append(validation_loss);
        if (self.validation_history.items.len > 100) {
            _ = self.validation_history.orderedRemove(0);
        }

        _ = train_loss;
    }
};

pub const ConvergenceMetrics = struct {
    step: usize,
    surprise_score: f32,
    spectral_norm: f32,
    convergence_certified: bool,
    lyapunov_decrease: f32,
};

pub const UltraOptimizer = struct {
    base_sfd: SFD,
    spectral_reg: AdaptiveSpectralRegularizer,
    variance_buffer: VarianceReducedBuffer,
    meta: MetaOptimizer,
    config: UltraOptimizerConfig,
    step: usize,
    variance_ema: Tensor,
    nesterov_buffer: Tensor,
    temperature: f32,
    privacy_budget: f32,

    pub fn init(allocator: Allocator, config: UltraOptimizerConfig) !UltraOptimizer {
        var base = try SFD.initWithConfig(allocator, config.param_size, config.sfd_config);
        errdefer base.deinit();

        var spectral = try AdaptiveSpectralRegularizer.init(
            allocator,
            1.0,
            config.spectral_adaptation_rate,
            50
        );
        errdefer spectral.deinit();

        var variance_buf = VarianceReducedBuffer.init(allocator, config.variance_buffer_size);
        errdefer variance_buf.deinit();

        var meta = try MetaOptimizer.init(allocator, 0.001, config.meta_lr);
        errdefer meta.deinit();

        const shape = [_]usize{config.param_size};
        var variance_ema = try Tensor.init(allocator, &shape);
        errdefer variance_ema.deinit();
        try variance_ema.fill(0.0);

        var nesterov = try Tensor.init(allocator, &shape);
        errdefer nesterov.deinit();
        try nesterov.fill(0.0);

        return UltraOptimizer{
            .base_sfd = base,
            .spectral_reg = spectral,
            .variance_buffer = variance_buf,
            .meta = meta,
            .config = config,
            .step = 0,
            .variance_ema = variance_ema,
            .nesterov_buffer = nesterov,
            .temperature = config.temperature,
            .privacy_budget = config.privacy_epsilon,
        };
    }

    pub fn deinit(self: *UltraOptimizer) void {
        self.base_sfd.deinit();
        self.spectral_reg.deinit();
        self.variance_buffer.deinit();
        self.meta.deinit();
        self.variance_ema.deinit();
        self.nesterov_buffer.deinit();
    }

    pub fn update(self: *UltraOptimizer, gradients: *const Tensor, params: *Tensor, input_surprise: f32) !ConvergenceMetrics {
        self.step += 1;

        const surprise = @min(input_surprise, 10.0);

        var working_grad = try gradients.clone();
        defer working_grad.deinit();

        if (self.config.enable_privacy and self.privacy_budget > 0.0) {
            const grad_norm = working_grad.normL2();
            if (grad_norm > self.config.gradient_clip_norm) {
                const scale = self.config.gradient_clip_norm / grad_norm;
                try working_grad.mulScalar(scale);
            }

            const noise_scale = self.config.gradient_clip_norm / (self.privacy_budget + self.config.sfd_config.eps);
            var rng = std.rand.DefaultPrng.init(@intCast(self.step));
            for (working_grad.data) |*g| {
                const noise = rng.random().floatNorm(f32) * noise_scale;
                g.* += noise;
            }

            self.privacy_budget -= 0.001;
        }

        try self.variance_buffer.push(working_grad);

        if (self.variance_buffer.buffer.items.len > 1) {
            const mean_grad = try self.variance_buffer.computeMean();
            defer mean_grad.deinit();

            for (working_grad.data, 0..) |*g, i| {
                g.* = g.* - mean_grad.data[i] + self.variance_ema.data[i];
            }

            const ema_decay = 0.95;
            for (self.variance_ema.data, 0..) |*v, i| {
                v.* = ema_decay * v.* + (1.0 - ema_decay) * gradients.data[i];
            }
        }

        var lookahead_params = try params.clone();
        defer lookahead_params.deinit();

        for (lookahead_params.data, 0..) |*p, i| {
            p.* += self.config.nesterov_momentum * self.nesterov_buffer.data[i];
        }

        for (working_grad.data, 0..) |*g, i| {
            const sign_based = if (g.* > 0.0) 1.0 else if (g.* < 0.0) -1.0 else 0.0;
            g.* = 0.7 * g.* + 0.3 * sign_based * @abs(g.*);
        }

        const surprise_factor = 1.0 + 0.3 * surprise;
        for (working_grad.data) |*g| {
            g.* *= surprise_factor;
        }

        const base_lr = self.meta.learning_rate;
        const thermal_scale = 1.0 / (1.0 + std.math.exp(-self.temperature));
        const adapted_lr = base_lr * thermal_scale * surprise_factor;

        try self.base_sfd.update(&working_grad, params, adapted_lr);

        for (self.nesterov_buffer.data, 0..) |*nb, i| {
            nb.* = self.config.nesterov_momentum * nb.* + working_grad.data[i];
        }

        if (self.step % 10 == 0) {
            try self.spectral_reg.adaptiveClip(params);
        }

        self.temperature *= 0.999;

        if (self.step % 50 == 0) {
            const dummy_train_loss: f32 = 0.1;
            const dummy_val_loss: f32 = 0.12;
            try self.meta.metaUpdate(dummy_train_loss, dummy_val_loss);
        }

        const current_spectral = params.spectralNorm(self.base_sfd.allocator, 50, 1e-5) catch 1.0;

        const lyapunov = self.computeLyapunov(params);

        return ConvergenceMetrics{
            .step = self.step,
            .surprise_score = surprise,
            .spectral_norm = current_spectral,
            .convergence_certified = self.config.enable_verification and lyapunov < 0.0,
            .lyapunov_decrease = lyapunov,
        };
    }

    fn computeLyapunov(self: *const UltraOptimizer, params: *const Tensor) f32 {
        var energy: f64 = 0.0;
        for (params.data) |p| {
            energy += @as(f64, p) * @as(f64, p);
        }
        return @floatCast(energy * 0.5);
    }

    pub fn saveState(self: *const UltraOptimizer, path: []const u8) !void {
        var file = try std.fs.cwd().createFile(path, .{ .mode = 0o600 });
        defer file.close();

        var buffered = std.io.bufferedWriter(file.writer());
        var writer = buffered.writer();

        try self.base_sfd.fisher_diag.save(writer);
        try self.base_sfd.momentum_buffer.save(writer);
        try self.base_sfd.velocity_buffer.save(writer);
        try self.variance_ema.save(writer);
        try self.nesterov_buffer.save(writer);

        try writer.writeInt(u64, @as(u64, self.step), .little);
        try writer.writeInt(u32, @as(u32, @bitCast(self.temperature)), .little);
        try writer.writeInt(u32, @as(u32, @bitCast(self.privacy_budget)), .little);
        try writer.writeInt(u32, @as(u32, @bitCast(self.meta.learning_rate)), .little);
        try writer.writeInt(u32, @as(u32, @bitCast(self.meta.beta1)), .little);
        try writer.writeInt(u32, @as(u32, @bitCast(self.meta.beta2)), .little);

        try buffered.flush();
    }

    pub fn loadState(self: *UltraOptimizer, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{ .mode = .read_only });
        defer file.close();

        var reader = file.reader();

        self.base_sfd.fisher_diag.deinit();
        self.base_sfd.fisher_diag = try Tensor.load(self.base_sfd.allocator, reader);

        self.base_sfd.momentum_buffer.deinit();
        self.base_sfd.momentum_buffer = try Tensor.load(self.base_sfd.allocator, reader);

        self.base_sfd.velocity_buffer.deinit();
        self.base_sfd.velocity_buffer = try Tensor.load(self.base_sfd.allocator, reader);

        self.variance_ema.deinit();
        self.variance_ema = try Tensor.load(self.base_sfd.allocator, reader);

        self.nesterov_buffer.deinit();
        self.nesterov_buffer = try Tensor.load(self.base_sfd.allocator, reader);

        self.step = @truncate(try reader.readInt(u64, .little));

        const temp_bits = try reader.readInt(u32, .little);
        self.temperature = @as(f32, @bitCast(temp_bits));

        const budget_bits = try reader.readInt(u32, .little);
        self.privacy_budget = @as(f32, @bitCast(budget_bits));

        const lr_bits = try reader.readInt(u32, .little);
        self.meta.learning_rate = @as(f32, @bitCast(lr_bits));

        const beta1_bits = try reader.readInt(u32, .little);
        self.meta.beta1 = @as(f32, @bitCast(beta1_bits));

        const beta2_bits = try reader.readInt(u32, .little);
        self.meta.beta2 = @as(f32, @bitCast(beta2_bits));
    }
};

